const papers = [
 {id:'anthropic',title:'Effective context engineering for AI agents',org:'Anthropic',year:'2025',kind:'Engineering article',tags:['start'],url:'https://www.anthropic.com/research/effective-context-engineering-for-ai-agents',why:'A practical introduction to selecting instructions, tools, and evidence for the current model call.',caveat:'Engineering guidance, not a controlled proof that shorter context always wins.',checked:'Original article read; context selection and tool-design sections used.'},
 {id:'gemini',title:'Gemini 1.5: Unlocking multimodal understanding across millions of tokens of context',org:'Google DeepMind',year:'2024',kind:'Technical report',tags:['start'],url:'https://www.alphaxiv.org/pdf/2403.05530',why:'Shows what expanded context can enable: long-input retrieval, document tasks, and learning from examples and reference materials.',caveat:'Retrieval success does not establish reliable multi-step agent behavior. These are the report’s historical models and tasks.',checked:'Full text consulted; long-context and in-context learning results checked.'},
 {id:'middle',title:'Lost in the Middle: How Language Models Use Long Contexts',org:'Liu et al.',year:'2023 / 2024',kind:'Research paper',tags:['start','novelty'],url:'https://www.alphaxiv.org/pdf/2307.03172',why:'Changes where evidence appears and shows position-dependent performance on the evaluated models.',caveat:'Do not assume every current model has the same curve; repeat the position test on your chosen model.',checked:'Original full text consulted.'},
 {id:'ruler',title:'RULER: What’s the Real Context Size of Your Long-Context Language Models?',org:'NVIDIA researchers',year:'2024',kind:'Benchmark paper',tags:['start','novelty'],url:'https://www.alphaxiv.org/pdf/2404.06654',why:'Goes beyond finding a single hidden fact with tasks involving multiple facts, tracing, and aggregation.',caveat:'Synthetic benchmark performance is not a substitute for end-to-end success in your application.',checked:'Original full text consulted.'},
 {id:'lurch',title:'Beyond Context Length: Characterising the Difficulty of Long-Context Reasoning',org:'University of Edinburgh',year:'2026',kind:'Recent preprint',tags:['recent','novelty'],url:'https://www.alphaxiv.org/pdf/2610.22067',why:'Distinguishes evidence scope, evidence dispersion, and reasoning depth. Equal-length tasks can impose very different demands.',caveat:'Reported relationships are largely observational; they motivate, but do not replace, controlled interventions.',checked:'Full text and original Figure 1 inspected.'},
 {id:'trained',title:'Trained Agentic Context Management',org:'Bryce Sandlund',year:'2026',kind:'Recent preprint',tags:['recent'],url:'https://www.alphaxiv.org/pdf/2610.02404',why:'Explores learned chunk-reading and recursive calls with a small per-call context. A future direction after simple input policies are understood.',caveat:'Training and additional calls change the comparison; it is not an isolated test of context length.',checked:'Original full text consulted. Training is outside our starter experiment.'},
 {id:'gsm',title:'Large Language Models Can Be Easily Distracted by Irrelevant Context',org:'Shi et al. · ICML',year:'2023',kind:'Research paper',tags:['novelty'],url:'https://proceedings.mlr.press/v202/shi23a.html',why:'Studies irrelevant context in mathematical reasoning and tests prompting mitigations.',caveat:'Establishes that distraction is prior work; our project cannot claim to invent testing irrelevant context.',checked:'Primary proceedings abstract read; not a full replication review.'},
 {id:'dim',title:'LLMs can be easily Confused by Instructional Distractions',org:'ACL',year:'2025',kind:'DIM-Bench',tags:['novelty'],url:'https://aclanthology.org/2025.acl-long.957/',why:'A close neighbor: tests whether models disregard instructional distractions across several tasks.',caveat:'Must compare its task construction against our scope-binding proposal before claiming benchmark novelty.',checked:'Primary proceedings abstract read; detailed novelty audit still needed.'},
 {id:'gsmdc',title:'How Is LLM Reasoning Distracted by Irrelevant Context?',org:'EMNLP',year:'2025',kind:'GSM-DC benchmark',tags:['novelty'],url:'https://aclanthology.org/2025.emnlp-main.674/',why:'Systematically varies irrelevant context in a controlled mathematical reasoning benchmark.',caveat:'Controlled distraction is already established. Our paired actions and applicability diagnostics must add something demonstrably different.',checked:'Primary abstract and proceedings PDF excerpts read; detailed novelty audit still needed.'}
];
const insights = [
 ['More context can unlock real capabilities.','DeepMind’s Gemini 1.5 report demonstrates long-input retrieval and learning from supplied materials. This supports testing where additional evidence helps, rather than assuming that smaller inputs are always better.','gemini','CAPABILITY'],
 ['Present does not mean successfully used.','Lost in the Middle finds position effects; RULER tests more than single-fact lookup. A model accepting a long input does not guarantee it will use every needed fact correctly.','middle','RELIABILITY'],
 ['Evidence structure matters.','LURCH distinguishes how much evidence is needed, how scattered it is, and how many reasoning steps connect it. These are useful variables for our experiment.','lurch','2026 RESEARCH'],
 ['Context is an engineering choice.','Anthropic recommends curating useful input and designing clear, efficient tools. We treat those recommendations as hypotheses to evaluate on the product’s own tasks.','anthropic','PRACTICE'],
 ['A small input can be part of a larger process.','Trained Agentic Context Management explores chunk-reading and recursive calls. Its training and extra computation are important confounds, so our first experiment freezes the model and measures all calls.','trained','2026 DIRECTION']
];
document.querySelector('#research-list').innerHTML=insights.map((x,i)=>{const p=papers.find(p=>p.id===x[2]);return `<article class="research-row"><span class="research-num">0${i+1}</span><div><span class="tag">${x[3]}</span><h3>${x[0]}</h3></div><div class="research-detail"><p>${x[1]}</p><a href="${p.url}" target="_blank" rel="noopener">${p.org} · ${p.year} ↗</a></div></article>`}).join('');
function renderSources(filter='all'){document.querySelector('#source-list').innerHTML=papers.filter(p=>filter==='all'||p.tags.includes(filter)).map(p=>`<article class="source-card"><div class="source-meta">${p.org} · ${p.year} · ${p.kind}</div><h3>${p.title}</h3><p>${p.why}</p><p><strong>Keep in mind:</strong> ${p.caveat}</p><a href="${p.url}" target="_blank" rel="noopener">Read the original source ↗</a><div class="checked">${p.checked}</div></article>`).join('')}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderSources(b.dataset.filter)}));renderSources();
const blocks=[
 {id:'river-rule',scope:'river',title:'River requirements',text:'12 people. Budget: $90. A room must fit the whole team. Video equipment is optional.'},
 {id:'summit-rule',scope:'summit',title:'Summit requirements',text:'4 people. Budget: $30. A room must fit the whole team. Working video equipment is required.'},
 {id:'shared-rule',scope:'shared',title:'Shared booking instruction',text:'Book exactly one available room that satisfies the target team’s requirements. If several qualify, choose the cheapest.'},
 {id:'other',scope:'other',title:'Another team’s policy',text:'The Studio team only books rooms priced above $100. This policy applies to Studio, not River or Summit.'},
 {id:'cedar',scope:'shared',title:'Cedar room',text:'Available. Capacity: 14 people. Price: $80. No video equipment.'},
 {id:'birch',scope:'shared',title:'Birch room',text:'Available. Capacity: 6 people. Price: $25. Video equipment works.'}
];
let team='river';
function renderDemo(){const policy=document.querySelector('#policy').value;const highlight=document.querySelector('#show-relevance').checked;const relevant=b=>b.scope===team||b.scope==='shared';let visible=policy==='recent'?blocks.slice(-2):policy==='selected'?blocks.filter(relevant):[...blocks];if(policy==='scoped')visible.sort((a,b)=>((a.scope===team?0:a.scope==='shared'?1:2)-(b.scope===team?0:b.scope==='shared'?1:2)));let prev='';document.querySelector('#context-blocks').innerHTML=visible.map(b=>{let heading='';const group=b.scope===team?'TARGET TEAM':b.scope==='shared'?'SHARED INFORMATION':'OTHER TEAMS';if(policy==='scoped'&&group!==prev){heading=`<div class="scope-heading">${group}</div>`;prev=group}return `${heading}<div class="context-block ${highlight?(relevant(b)?'needed':'distractor'):''}"><span class="block-meta">${b.scope.toUpperCase()}</span><strong>${b.title}</strong><p>${b.text}</p></div>`}).join('');document.querySelector('#block-count').textContent=`${visible.length} / 6 blocks`;document.querySelector('#demo-question').textContent=`Choose and book a room for ${team==='river'?'River':'Summit'}.`;const explains={full:['Everything is visible.','All requirements and options are present. The model still has to apply the target team’s rules and ignore the others. We cannot infer its accuracy from visibility alone.'],recent:['Options survive; requirements disappear.','The last two blocks contain room choices but omit the team constraints and shared instruction. This is evidence loss, before reasoning even begins.'],selected:['A smaller, applicable packet.','The illustration filters explicit scope labels and retains shared information. This preserves the needed evidence here; it does not prove a general selector will do so.'],scoped:['Same facts, clearer boundaries.','Grouping changes presentation while preserving the original six blocks and their scope labels. Whether it prevents wrong-scope decisions is an experimental question.']};document.querySelector('#demo-explanation').innerHTML=`<strong>${explains[policy][0]}</strong>${explains[policy][1]}`;document.querySelector('#demo-answer').textContent=team==='river'?'Book Cedar: it fits 12 people and costs $80, within the $90 budget. Birch is too small. Summit’s video requirement does not apply to River.':'Book Birch: it fits 4 people, costs $25, and has working video. Cedar exceeds Summit’s $30 budget and has no video. River’s larger capacity requirement does not apply to Summit.';}
document.querySelectorAll('[data-team]').forEach(b=>b.addEventListener('click',()=>{team=b.dataset.team;document.querySelectorAll('[data-team]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderDemo()}));document.querySelector('#policy').addEventListener('change',renderDemo);document.querySelector('#show-relevance').addEventListener('change',renderDemo);renderDemo();
const domains={coding:['Coding agents','A bug report, relevant functions, dependency contracts, and test output.','A small local fix may need only a few files. A behavior change spanning modules may need several connected definitions.','A rule for one package gets applied to another, or an exception in a distant caller is omitted.'],research:['Research assistants','The question, primary evidence, methods, and limitations.','One factual lookup can be local. Comparing methods needs evidence distributed across several papers.','A result is transferred across incompatible experiments, datasets, or evaluation settings.'],support:['Customer support','The current request, applicable policy, and current account facts.','A specific answer may need only a policy clause and an account field, while an exception needs additional conditions.','A policy for a different plan, region, or date governs the answer.'],planning:['Planning agents','Goals, available options, hard constraints, and current task state.','A simple choice can be compact; a plan with interacting constraints needs their joint context.','The agent meets most requirements but silently violates one necessary constraint.'],vision:['Images & video','The question plus relevant images, frames, audio, or extracted observations.','A single frame may answer an object question. An event-order question may require several time points.','An isolated crop removes the relation or sequence needed to interpret the scene.']};
function renderDomain(key){const d=domains[key];document.querySelector('#domain-content').innerHTML=`<div><span class="small-label">WHAT CONTEXT CONTAINS</span><h3>${d[0]}</h3><p>${d[1]}</p></div><div><span class="small-label">WHEN MORE MAY BE NEEDED</span><p>${d[2]}</p></div><div><span class="small-label">FAILURE TO LOOK FOR</span><p>${d[3]}</p></div>`}document.querySelectorAll('[data-domain]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-domain]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderDomain(b.dataset.domain)}));renderDomain('coding');
const decisions=[
 ['Limited wins; required evidence is present','Improve the context selector.','Extra material may be interfering. Before concluding that shorter is better, check the matched-evidence distractor contrast and total selection cost.','Next test: compare unrelated filler and similar but inapplicable rules at equal length.'],
 ['Limited loses; needed evidence is missing','Fix coverage before the prompt.','The model never received everything it needed. Increase selection coverage, preserve exceptions, or increase the budget. This does not establish weak reasoning.','Next test: supply the omitted evidence in an oracle rescue, removing equal-length filler.'],
 ['Evidence is complete; another team’s rule wins','Make scope explicit.','A wrong-scope action is consistent with an applicability failure. Grouping or clearer entity labels may help; confirm with the paired formatting intervention.','Next test: use identical facts and labels, grouped versus interleaved, at matched lengths.'],
 ['Even the evidence-only diagnostic fails','Simplify and inspect the task.','Possible causes include reasoning, instruction following, tool use, or a faulty benchmark. Inspect gold answers and try an easier task before changing context policy.','Next test: reduce reasoning depth while holding the necessary evidence explicit.'],
 ['All methods look similar','Find out whether the task is too easy.','Similar pilot scores can reflect insufficient difficulty or uncertainty. They do not establish equivalence. If a larger study supports non-inferiority, prefer the simpler, cheaper policy.','Next test: predeclare a practical margin, expand held-out pairs, and increase exception or scope-collision difficulty.'],
 ['A win disappears on a second domain','Keep the claim narrow.','The policy may depend on your task templates or metadata. Avoid turning one benchmark win into a general context-management product claim.','Next test: freeze the policy and transfer it to coding or customer-support packets without retuning.']
];
function renderDecision(i){const d=decisions[i];document.querySelector('#decision-answer').innerHTML=`<span class="small-label">WHAT THIS WOULD SUGGEST</span><h3>${d[1]}</h3><p>${d[2]}</p><p class="next-test">${d[3]}</p>`;document.querySelectorAll('[data-decision]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.decision===i)))}document.querySelector('#decision-buttons').innerHTML=decisions.map((d,i)=>`<button data-decision="${i}" aria-pressed="${i===0}"><span>${d[0]}</span><span>↗</span></button>`).join('');document.querySelectorAll('[data-decision]').forEach(b=>b.addEventListener('click',()=>renderDecision(+b.dataset.decision)));renderDecision(0);
